/**
 * Source scanning: TODO/FIXME/HACK extraction and "boss taunt" comment mining.
 * Pure string processing, shared by the GitHub fetcher and the local CLI.
 */
import type { ScannedFile, TodoItem, TodoKind } from './types.js';
import { truncate } from './format.js';

const COMMENT_MARKER = String.raw`(?:\/\/+!?|\/\*+!?|^\s*\*+|#+|--+|;+|<!--|\{-|\(\*|%+|^\s*'|\bREM\b)`;
const KEYWORD = String.raw`(TODO|FIXME|HACK|XXX|BUG|todo(?=\s*[:(])|fixme(?=\s*[:(]))`;
const TODO_RE = new RegExp(
  `${COMMENT_MARKER}[ \\t]*@?${KEYWORD}\\b(?:\\(([^)]{0,48})\\))?[ \\t]*[:\\-–—!]?[ \\t]*(.*)$`,
);

const TRAILING_CLOSERS = /\s*(\*+\/|-->|-\}|\*\)|"""|''')\s*$/;

/** Extract TODO-style comments from file content. */
export function extractTodos(path: string, content: string, max = 200): TodoItem[] {
  const out: TodoItem[] = [];
  const lines = content.split(/\r?\n/);
  for (let i = 0; i < lines.length && out.length < max; i++) {
    const line = lines[i];
    if (line.length > 400) continue; // minified / generated
    if (!/TODO|FIXME|HACK|XXX|BUG|todo|fixme/.test(line)) continue;
    const m = TODO_RE.exec(line);
    if (!m) continue;
    const kind = m[1].toUpperCase() as TodoKind;
    // `XXX` and `BUG` are noisy; require them to be followed by a colon or text start.
    if ((kind === 'XXX' || kind === 'BUG') && !/^\s*[:(]/.test(line.slice(m.index + m[0].indexOf(m[1]) + m[1].length))) {
      continue;
    }
    let text = (m[3] ?? '').replace(TRAILING_CLOSERS, '').trim();
    text = text.replace(/\s+/g, ' ');
    // Skip commented-out code that merely mentions the word.
    if (/^[=;{}()[\]]/.test(text)) continue;
    const item: TodoItem = { path, line: i + 1, kind, text: truncate(text, 120) };
    const owner = m[2]?.trim();
    if (owner) item.owner = truncate(owner, 40);
    out.push(item);
  }
  return out;
}

const LINE_COMMENT_RE =
  /^\s*(?:\/\/+!?|#+(?!!)(?!\s*(?:include|define|undef|if|ifdef|ifndef|else|elif|endif|pragma|import|region|endregion|error|warning|line)\b)|--(?!-)|;+)\s?(.*)$/;
const BLOCK_LINE_RE = /^\s*(?:\/\*+|\*+(?!\/))\s?(.*?)(?:\*\/)?\s*$/;

const TAUNT_BLOCKLIST =
  /(copyright|licen[cs]e|spdx|eslint|prettier|istanbul|@flow|@ts-|noqa|type:\s*ignore|pylint|nolint|clang-format|@param|@return|@throws|@type|@typedef|@see|@since|@deprecated|@author|@internal|@private|@public|@example|generated by|auto-?generated|do not edit|-\*-|vim:|http:\/\/|https:\/\/|#region|#endregion|\bc8\b|rustfmt|pragma|^\s*[-=*#~_]{3,})/i;

const CODE_LIKE = /([;{}]\s*$|^\s*(if|for|while|return|var|let|const|import|from|def|function|fn|func|class|public|private|static|else|elif|switch|case|try|catch|throw|await|async|yield|print|console\.)\b|[=!]==|=>|\)\s*\{|^\s*[a-zA-Z_$][\w$.]*\s*\(.*\)\s*;?$)/;

const SPICY = [
  "don't", 'do not', 'never', 'always', 'careful', 'hack', 'magic', 'why', 'sorry', 'ugly', 'temporary', 'temporarily',
  'workaround', 'legacy', 'todo', 'fixme', 'bug', 'weird', 'horrible', 'evil', 'danger', 'warning', 'beware', 'wtf',
  'lol', 'yolo', 'trust', 'pray', 'god', 'guess', 'somehow', 'unfortunately', 'assume', 'cannot', "can't", "won't",
  "shouldn't", 'deprecated', 'later', 'hope', 'probably', 'crazy', 'insane', 'gross', 'nasty', 'terrible', 'oops',
  'kludge', 'dragons', 'brittle', 'fragile', 'scary', 'here be', 'must', 'important',
];

/** Mine the comment lines of a file for funny/ominous one-liners. */
export function extractTaunts(content: string, max = 10): string[] {
  const seen = new Set<string>();
  const scored: { text: string; score: number; order: number }[] = [];
  const lines = content.split(/\r?\n/);
  let inBlock = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.length > 300) continue;
    let text: string | null = null;
    if (inBlock) {
      if (line.includes('*/')) inBlock = false;
      const m = BLOCK_LINE_RE.exec(line);
      text = m ? m[1] : null;
    } else {
      const lm = LINE_COMMENT_RE.exec(line);
      if (lm) {
        text = lm[1];
      } else if (/^\s*\/\*/.test(line)) {
        inBlock = !line.includes('*/');
        const bm = BLOCK_LINE_RE.exec(line);
        text = bm ? bm[1] : null;
      }
    }
    if (!text) continue;
    text = text.replace(/\s+/g, ' ').trim();
    if (text.length < 14 || text.length > 96) continue;
    if (text.split(' ').length < 3) continue;
    if (TAUNT_BLOCKLIST.test(text)) continue;
    if (CODE_LIKE.test(text)) continue;
    if (!/[a-z]/i.test(text)) continue;
    const key = text.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    const lower = key;
    let score = 0;
    for (const word of SPICY) if (lower.includes(word)) score += 2;
    if (text.length >= 24 && text.length <= 72) score += 1;
    if (/[!?]/.test(text)) score += 1;
    if (/^[A-Z]/.test(text)) score += 0.5;
    scored.push({ text, score, order: i });
  }
  scored.sort((a, b) => b.score - a.score || a.order - b.order);
  return scored.slice(0, max).map((s) => s.text);
}

export function countLines(content: string): number {
  if (content.length === 0) return 0;
  let n = 1;
  for (let i = 0; i < content.length; i++) if (content.charCodeAt(i) === 10) n++;
  // A trailing newline does not start a new line.
  if (content.charCodeAt(content.length - 1) === 10) n--;
  return n;
}

const GENERATED_MARKER =
  /(@generated\b|do not edit|auto-?generated|automatically generated|this file (is|was|has been) (auto-?)?generated|machine generated|code generated .{0,80}do not edit)/i;
/** Weaker phrasing only counts in the file header. */
const HEADER_GENERATED = /\b(generated|created) (by|from|with|using) \S+/i;
const BUNDLE_MARKER = /(__webpack_require__|webpackBootstrap|\bdefine\.amd\b|\(function\s*\(\s*(global|root)\s*,\s*factory\s*\)|\bSystem\.register\(|parcelRequire)/;

/**
 * Content-based check for generated, bundled, minified or pure-data files.
 * These make terrible bosses (nobody wrote 40,000 lines of #defines by hand).
 */
export function detectGenerated(content: string, lines = countLines(content)): boolean {
  const head = content.slice(0, 4000);
  if (GENERATED_MARKER.test(head)) return true;
  if (HEADER_GENERATED.test(content.slice(0, 300)) && /generat/i.test(content.slice(0, 300))) return true;
  if (/sourceMappingURL=/.test(content.slice(-600))) return true;
  if (/^\s*\/\*!/.test(head) && BUNDLE_MARKER.test(content.slice(0, 200_000))) return true;
  if (BUNDLE_MARKER.test(head)) return true;
  if (lines > 0 && content.length / lines > 220) return true; // minified
  if (lines > 1200) {
    const all = content.split(/\r?\n/);
    const step = Math.max(1, Math.floor(all.length / 400));
    let sampled = 0;
    let dataLike = 0;
    for (let i = 0; i < all.length; i += step) {
      const line = all[i].trim();
      if (!line) continue;
      sampled++;
      if (
        /^#\s*define\s+\w+\s+\(?(0x[0-9a-f]+|\d+)[ul]*\)?$/i.test(line) ||
        /^[\s\d,.\-+x{}a-f()_|<>]+,?$/i.test(line) ||
        /^["'`][^"'`]*["'`]\s*[,:;]?\s*(["'`][^"'`]*["'`]\s*,?)?$/.test(line) ||
        /^(\{\s*)?0x[0-9a-f]+\s*,/i.test(line)
      ) {
        dataLike++;
      }
    }
    if (sampled > 50 && dataLike / sampled > 0.6) return true;
  }
  return false;
}

/** Turn raw file content into a ScannedFile. */
export function scanContent(path: string, content: string, opts: { taunts?: boolean } = {}): ScannedFile {
  const lines = countLines(content);
  const file: ScannedFile = {
    path,
    lines,
    todos: extractTodos(path, content),
  };
  if (detectGenerated(content, lines)) file.generated = true;
  if (opts.taunts && !file.generated) file.comments = extractTaunts(content);
  return file;
}

/** Heuristic: content looks binary (NUL bytes in the first chunk). */
export function looksBinary(content: string): boolean {
  const head = content.slice(0, 2000);
  return head.includes('\u0000');
}
